class Solution {
    public java.util.List<String> removeInvalidParentheses(String s) {
        java.util.List<String> result = new java.util.ArrayList<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        queue.offer(s);
        visited.add(s);
        boolean found = false;

        while (!queue.isEmpty()) {
            for (int size = queue.size(); size > 0; size--) {
                String current = queue.poll();
                if (isValid(current)) {
                    result.add(current);
                    found = true;
                }
                if (found) {
                    continue;
                }
                for (int i = 0; i < current.length(); i++) {
                    char c = current.charAt(i);
                    if (c != '(' && c != ')') {
                        continue;
                    }
                    String next = current.substring(0, i) + current.substring(i + 1);
                    if (visited.add(next)) {
                        queue.offer(next);
                    }
                }
            }
            if (found) {
                break;
            }
        }
        return result;
    }

    private boolean isValid(String value) {
        int balance = 0;
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
                if (balance < 0) {
                    return false;
                }
            }
        }
        return balance == 0;
    }
}

class Solution {
    public java.util.List<String> removeInvalidParentheses(String s) {
        int removeLeft = 0;
        int removeRight = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                removeLeft++;
            } else if (c == ')') {
                if (removeLeft > 0) {
                    removeLeft--;
                } else {
                    removeRight++;
                }
            }
        }

        java.util.Set<String> result = new java.util.HashSet<>();
        dfs(s, 0, 0, removeLeft, removeRight, new StringBuilder(), result);
        return new java.util.ArrayList<>(result);
    }

    private void dfs(String s, int index, int open, int removeLeft, int removeRight,
                     StringBuilder builder, java.util.Set<String> result) {
        if (index == s.length()) {
            if (open == 0 && removeLeft == 0 && removeRight == 0) {
                result.add(builder.toString());
            }
            return;
        }

        char c = s.charAt(index);
        int length = builder.length();
        if (c == '(' && removeLeft > 0) {
            dfs(s, index + 1, open, removeLeft - 1, removeRight, builder, result);
        }
        if (c == ')' && removeRight > 0) {
            dfs(s, index + 1, open, removeLeft, removeRight - 1, builder, result);
        }

        builder.append(c);
        if (c == '(') {
            dfs(s, index + 1, open + 1, removeLeft, removeRight, builder, result);
        } else if (c == ')') {
            if (open > 0) {
                dfs(s, index + 1, open - 1, removeLeft, removeRight, builder, result);
            }
        } else {
            dfs(s, index + 1, open, removeLeft, removeRight, builder, result);
        }
        builder.setLength(length);
    }
}

class Solution {
    public java.util.List<String> removeInvalidParentheses(String s) {
        java.util.List<String> result = new java.util.ArrayList<>();
        remove(s, result, 0, 0, new char[]{'(', ')'});
        return result;
    }

    private void remove(String s, java.util.List<String> result, int scanStart, int removeStart, char[] par) {
        int balance = 0;
        for (int i = scanStart; i < s.length(); i++) {
            if (s.charAt(i) == par[0]) {
                balance++;
            }
            if (s.charAt(i) == par[1]) {
                balance--;
            }
            if (balance >= 0) {
                continue;
            }

            for (int j = removeStart; j <= i; j++) {
                if (s.charAt(j) == par[1]
                        && (j == removeStart || s.charAt(j - 1) != par[1])) {
                    remove(s.substring(0, j) + s.substring(j + 1), result, i, j, par);
                }
            }
            return;
        }

        String reversed = new StringBuilder(s).reverse().toString();
        if (par[0] == '(') {
            remove(reversed, result, 0, 0, new char[]{')', '('});
        } else {
            result.add(reversed);
        }
    }
}

class Solution {
    public java.util.List<String> removeInvalidParentheses(String s) {
        int removeLeft = 0;
        int removeRight = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                removeLeft++;
            } else if (c == ')') {
                if (removeLeft > 0) {
                    removeLeft--;
                } else {
                    removeRight++;
                }
            }
        }

        int targetLength = s.length() - removeLeft - removeRight;
        java.util.Set<String> result = new java.util.HashSet<>();
        backtrack(s, 0, targetLength, 0, new StringBuilder(), result);
        return new java.util.ArrayList<>(result);
    }

    private void backtrack(String s, int index, int targetLength, int balance,
                           StringBuilder builder, java.util.Set<String> result) {
        int remaining = s.length() - index;
        if (builder.length() + remaining < targetLength) {
            return;
        }
        if (builder.length() > targetLength || balance < 0) {
            return;
        }
        if (index == s.length()) {
            if (builder.length() == targetLength && balance == 0) {
                result.add(builder.toString());
            }
            return;
        }

        char c = s.charAt(index);
        int length = builder.length();
        if (c == '(' || c == ')') {
            backtrack(s, index + 1, targetLength, balance, builder, result);
        }

        builder.append(c);
        if (c == '(') {
            backtrack(s, index + 1, targetLength, balance + 1, builder, result);
        } else if (c == ')') {
            backtrack(s, index + 1, targetLength, balance - 1, builder, result);
        } else {
            backtrack(s, index + 1, targetLength, balance, builder, result);
        }
        builder.setLength(length);
    }
}
